contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(amount > 0);
        require(address(this).balance + address(c).balance >= amount);
        uint beforeBal = address(this).balance;
        c.sendTo(address(this), amount); if (__ESBMC_reverted()) return;
        assert(address(this).balance == beforeBal + amount);
    }
    receive() external payable {}
}

